 async function uploadAvatar(file:File){if(!supabase||!uid)return;if(!file.type.startsWith('image/')){setNotice('اختاري صورة فقط');return;}setUploading(true);try{const img=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,480/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('تعذر معالجة الصورة');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let blob:Blob|null=null;for(const q of [0.75,0.6,0.45,0.3,0.2]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',q));if(blob&&blob.size<=50*1024)break;}if(!blob||blob.size>50*1024)throw Error('لم نتمكن من ضغط الصورة إلى 50 كيلوبايت');const path=uid+'/avatar.jpg';const {error}=await supabase.storage.from('nabt-avatars').upload(path,blob,{contentType:'image/jpeg',upsert:true});if(error)throw Error('تخزين الصور غير مهيأ بعد: '+error.message);const {data}=supabase.storage.from('nabt-avatars').getPublicUrl(path);const newUrl=data.publicUrl+'?v='+Date.now();const saved=await supabase.auth.updateUser({data:{avatar_url:newUrl}});if(saved.error)throw saved.error;setAvatar(newUrl);setNotice('تم ضغط الصورة ورفعها بنجاح ('+Math.ceil(blob.size/1024)+' كيلوبايت)');}catch(err){setNotice(err instanceof Error?err.message:'تعذر رفع الصورة');}finally{setUploading(false);}}
